python3 -c "
import json
with open('/app/resources/treasury_bulletin_1991_09.json') as f:
    data = json.load(f)
doc = data['document']
# Page 16 = index 15. But let's check ALL pages for actual content
# (non-image pages)
for i, page in enumerate(doc['pages']):
    if len(page.keys()) > 1:  # More than just 'id' and 'image_uri'
        print(f'Page {i}: keys = {list(page.keys())}')
        if 'elements' in page:
            for j, el in enumerate(page['elements'][:5]):
                print(f'  el[{j}]: type={el.get(\"type\")}, keys={list(el.keys())}')
                if el.get('type') == 'text':
                    print(f'    text[:150]={str(el.get(\"text\",\"\"))[:150]}')
                elif el.get('type') == 'chart':
                    print(f'    chart: {str(el)[:300]}')
                elif el.get('type') == 'table':
                    print(f'    table: {str(el)[:300]}')
" 2>&1 | head -100
